import{_ as e,c as o,o as t,ag as i}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"安装","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/installation.md","filePath":"zh-CN/guide/installation.md","lastUpdated":1791311600000}'),r={name:"zh-CN/guide/installation.md"};function l(n,a,s,d,h,c){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><p>nPlyr 来自同一个 Xcode 工程的两个 target：</p><ul><li><strong><code>nPlyr</code></strong>——macOS 应用。</li><li><strong><code>nPlyrIOS</code></strong>——iOS / iPadOS 应用。</li></ul><p>两者共用同一套播放内核与规则引擎。</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><h3 id="mac-app-store-推荐" tabindex="-1">Mac App Store（推荐） <a class="header-anchor" href="#mac-app-store-推荐" aria-label="Permalink to &quot;Mac App Store（推荐）&quot;">​</a></h3><ol><li>打开 <strong>Mac App Store</strong>，搜索 <strong>nPlyr</strong>，或使用<a href="/zh-CN/">首页</a>上的徽章。</li><li>点击 <strong>获取</strong>，等待下载完成。</li><li>从 Dock 或启动台启动 nPlyr。</li></ol><p>Mac App Store 版本经过沙盒化并由 Apple 签名，因此无需额外设置。</p><h3 id="侧载-开发-testflight" tabindex="-1">侧载（开发 / TestFlight） <a class="header-anchor" href="#侧载-开发-testflight" aria-label="Permalink to &quot;侧载（开发 / TestFlight）&quot;">​</a></h3><p>如果你从源码构建，请打开 <code>nPlyr.xcodeproj</code>，选择 <strong><code>nPlyr</code></strong> scheme，并在&quot;My Mac&quot;上运行。开发签名构建在首次使用浏览器或下载功能时，可能会提示你授予<a href="/zh-CN/guide/permissions.html">权限</a>中描述的权限。</p><h2 id="ios-ipados" tabindex="-1">iOS / iPadOS <a class="header-anchor" href="#ios-ipados" aria-label="Permalink to &quot;iOS / iPadOS&quot;">​</a></h2><h3 id="app-store" tabindex="-1">App Store <a class="header-anchor" href="#app-store" aria-label="Permalink to &quot;App Store&quot;">​</a></h3><p>在 iOS App Store 中搜索 <strong>nPlyr</strong> 并安装。同一个账号可在两个平台上解锁小程序功能。</p><h3 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h3><ol><li>打开 <code>nPlyr.xcodeproj</code> 并选择 <strong><code>nPlyrIOS</code></strong> scheme。</li><li>选择一个模拟器或已连接的设备（iOS 16+）。</li><li>运行。在实体设备上，你需要在 Signing &amp; Capabilities 中设置一个开发团队。</li></ol><blockquote><p>iOS 构建与 macOS 使用同一套共享源码；只有少量平台胶水文件不同。没有独立的 <code>ffmpeg</code> 依赖。</p></blockquote><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to &quot;首次启动&quot;">​</a></h2><p>首次启动时，nPlyr 会：</p><ul><li>请求它所需的权限（参见<a href="/zh-CN/guide/permissions.html">权限</a>），</li><li>在用户数据容器内创建本地媒体库，</li><li>默认使用你的系统语言（可随时在<a href="/zh-CN/guide/settings.html">设置</a>中切换）。</li></ul><p>如果安装后某些行为不符合预期，请跳转到<a href="/zh-CN/guide/troubleshooting.html">故障排查</a>。</p>',20)])])}const g=e(r,[["render",l]]);export{u as __pageData,g as default};
